parameters.jsonBody:
={{ JSON.stringify({
  model: "qwen3:14b",
  stream: false,
  think: false,
  messages: [
    { role: "system", content: "You are reviewing one conversation transcript between a user and Amy (an AI assistant) to score it and diagnose any problems.\n\nScore five dimensions independently, each an integer 1-5 (1=very bad, 5=excellent):\n- task_success_score: did Amy actually accomplish what the user needed?\n- relevance_score: was Amy's reply relevant and on-topic, without irrelevant padding?\n- persona_alignment_score: did Amy's tone/behavior match her persona (see persona text below)?\n- user_sentiment_score: based on the user's own words/reactions, how pleased or frustrated did they seem?\n- followup_coherence_score: if there was a follow-up exchange, did Amy's later replies make sense given what was said before, including respecting corrections?\n\nThen list every distinct root cause you can identify for anything that scored below 4 in any dimension. A single symptom can have more than one independent cause - do not stop at the first plausible explanation, keep looking for others. For each cause, output one attribution object with:\n- type: one of persona_text, honcho_peer_card, model_capability_limitation, tool_failure, ambiguous_user_request, none\n- confidence: 0.0-1.0\n- evidence: a short quote from the transcript or tool trace that supports this attribution - never invent a quote\n- suggested_fix_area: a short phrase pointing at what should change\n\nIf nothing scored below 4, return a single attribution with type \"none\".\n\nIf no tool-call trace was available for this session, do not assume tool_failure without other direct evidence already present in the transcript text itself." },
    { role: "user", content: $json.userContent }
  ],
  options: { num_ctx: 16384 },
  format: {
    type: "object",
    properties: {
      task_success_score: { type: "integer" },
      relevance_score: { type: "integer" },
      persona_alignment_score: { type: "integer" },
      user_sentiment_score: { type: "integer" },
      followup_coherence_score: { type: "integer" },
      overall_notes: { type: "string" },
      attributions: {
        type: "array",
        items: {
          type: "object",
          properties: {
            type: { type: "string" },
            confidence: { type: "number" },
            evidence: { type: "string" },
            suggested_fix_area: { type: "string" }
          },
          required: ["type", "confidence", "evidence"]
        }
      }
    },
    required: ["task_success_score","relevance_score","persona_alignment_score","user_sentiment_score","followup_coherence_score","attributions"]
  }
}) }}

parameters.jsCode:
let parsed;
try {
  parsed = JSON.parse($json.message.content);
} catch (e) {
  parsed = {
    task_success_score: 3, relevance_score: 3, persona_alignment_score: 3,
    user_sentiment_score: 3, followup_coherence_score: 3,
    overall_notes: 'Judge output failed to parse: ' + e.message,
    attributions: [{ type: 'none', confidence: 0, evidence: 'parse failure', suggested_fix_area: null }],
  };
}
const clamp = (n) => Math.max(1, Math.min(5, Math.round(Number(n) || 3)));
return [{
  json: {
    task_success_score: clamp(parsed.task_success_score),
    relevance_score: clamp(parsed.relevance_score),
    persona_alignment_score: clamp(parsed.persona_alignment_score),
    user_sentiment_score: clamp(parsed.user_sentiment_score),
    followup_coherence_score: clamp(parsed.followup_coherence_score),
    overall_notes: parsed.overall_notes || '',
    attributions: (Array.isArray(parsed.attributions) && parsed.attributions.length)
      ? parsed.attributions
      : [{ type: 'none', confidence: 0, evidence: '', suggested_fix_area: null }],
    raw_judge_output: parsed,
  },
}];
